#[derive(Debug, PartialEq)]
enum OutputRow<'a> {
    /// Reply text; empty while its first words are on their way.
    Text(&'a str),
    Tool(&'a ToolCall),
    Error(&'a str),
    /// The harness is still at work, and nothing is known of what comes next.
    Pending,
}

